#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fit_cells_keeps_contextual_emoji_whole() {
        assert_eq!(fit_cells(" 👩‍💻 tail", 4), " 👩‍💻 ");
        assert!(UnicodeWidthStr::width(fit_cells("界界", 3).as_str()) <= 3);
    }
}

